def _torch_sort(data):
    x, out = data
    out.copy_(torch.sort(x)[0])
    return out
_ARMS.pop("rotk", None)

_done = False
def custom_kernel(data):
    global _done
    x, out = data
    if _done or x.numel() != 4096:
        return _ARMS["v1i"](data)
    _done = True
    from reference import generate_input
    from utils import clear_l2_cache
    n, seed = 100_000_000, 6252
    sig = inspect.signature(generate_input).parameters
    def gen(s):
        kw = {"size": n, "seed": s}
        return generate_input(**{k: v for k, v in kw.items() if k in sig})
    lines = ["generate_input" + str(inspect.signature(generate_input))]
    base = gen(seed)
    ref = torch.sort(base[0])[0]
    res = {(a, m): ([], []) for a in _ARMS for m in ("NEW",)}
    for a in _ARMS:                                   # warm each arm once + correctness
        o = torch.empty_like(base[0]); _ARMS[a]((base[0], o)); torch.cuda.synchronize()
        lines.append(f"{a}: correct={torch.equal(o, ref)}")
    s = seed
    for rep in range(3):
        for a in _ARMS:
            for m in ("NEW",):
                if m == "NEW":
                    s += 13
                    d = gen(s)
                else:
                    d = base
                torch.cuda.synchronize()
                e0 = torch.cuda.Event(enable_timing=True); e1 = torch.cuda.Event(enable_timing=True)
                clear_l2_cache()
                e0.record()
                h0 = time.perf_counter()
                _ARMS[a](d)
                h1 = time.perf_counter()
                e1.record()
                torch.cuda.synchronize()
                res[(a, m)][0].append(e0.elapsed_time(e1) * 1000.0)
                res[(a, m)][1].append((h1 - h0) * 1e6)
    for (a, m), (g, h) in res.items():
        lines.append(f"{a:5s} {m}: mean={statistics.mean(g):7.0f} median={statistics.median(g):7.0f} "
                     f"min={min(g):7.0f} host_mean={statistics.mean(h):7.0f} us  all={[round(v) for v in g]}")
    raise RuntimeError("DIAG-AB\n" + "\n".join(lines))
